-- F3 · TACO 4ª ed. (NEPA/UNICAMP, 2011), 597 alimentos por 100 g, em foods (code 'taco:<n>').
-- Fonte: TACO – Tabela Brasileira de Composição de Alimentos, 4ª ed. revisada e ampliada. NEPA/UNICAMP, Campinas, 2011
-- (planilha original via github.com/raulfdm/taco-api). 'Tr' = 0; 'NA'/'*' = null. Kcal inteiro, macros com 1 casa.
-- + medidas caseiras iniciais (food_portions); o bot acrescenta outras com o uso (fit portion).

on conflict (code) do update set name = excluded.name, category = excluded.category, kcal = excluded.kcal,
  protein_g = excluded.protein_g, carb_g = excluded.carb_g, fat_g = excluded.fat_g, fiber_g = excluded.fiber_g;

select f.id, p.label, p.grams, 'bot'
from (values
  ('taco:3', '1 colher de sopa cheia', 25),
  ('taco:3', '1 escumadeira', 90),
  ('taco:1', '1 colher de sopa cheia', 25),
  ('taco:1', '1 escumadeira', 90),
  ('taco:561', '1 concha média', 140),
  ('taco:561', '1 colher de sopa', 20),
  ('taco:567', '1 concha média', 140),
  ('taco:410', '1 filé médio', 100),
  ('taco:410', '1 filé grande', 150),
  ('taco:488', '1 unidade', 50),
  ('taco:490', '1 unidade', 50),
  ('taco:182', '1 unidade média', 65),
  ('taco:53', '1 unidade', 50),
  ('taco:52', '1 fatia', 25),
  ('taco:260', '1 colher de sopa', 8),
  ('taco:272', '1 colher de sopa', 8),
  ('taco:7', '1 colher de sopa', 15),
  ('taco:88', '1 unidade média', 130),
  ('taco:88', '1 pedaço médio', 80),
  ('taco:129', '1 pedaço médio', 70),
  ('taco:377', '1 bife médio', 100),
  ('taco:326', '1 colher de sopa cheia', 25),
  ('taco:461', '1 fatia média', 30),
  ('taco:463', '1 fatia', 15),
  ('taco:448', '1 pote', 170),
  ('taco:471', '1 xícara de café', 50),
  ('taco:492', '1 colher de chá', 5),
  ('taco:492', '1 colher de sopa', 12),
  ('taco:261', '1 ponta de faca', 5),
  ('taco:222', '1 unidade média', 130),
  ('taco:226', '1/2 unidade', 150),
  ('taco:214', '1 unidade', 140),
  ('taco:215', '1 copo', 200),
  ('taco:157', '1 unidade média', 100),
  ('taco:91', '1 unidade média', 120),
  ('taco:533', '1 pedaço médio', 100),
  ('taco:100', '1 xícara', 70),
  ('taco:163', '1 colher de sopa', 30),
  ('taco:140', '1 unidade média', 25),
  ('taco:507', '1 colher de sopa', 20),
  ('taco:277', '1 lata drenada', 120),
  ('taco:398', '1 unidade', 70),
  ('taco:540', '1 concha', 150),
  ('taco:557', '1 colher de sopa', 15),
  ('taco:498', '1 quadrado', 5)
) as p(code, label, grams)
join public.foods f on f.code = p.code
on conflict (food_id, label) do nothing;
